'use strict';
// node report_alloy_presets_browser_test.cjs PLAYWRIGHT OUTPUT PRESETS_JSON
// PRESETS_JSON is generated by JSON.json(report_alloy_presets()) from src/materials.jl.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const [modulePath,output,presetsFile]=process.argv.slice(2),web=path.resolve(__dirname,'../web');
if(!modulePath||!output||!presetsFile)throw Error('Expected PLAYWRIGHT, OUTPUT and PRESETS_JSON');
const presets=JSON.parse(fs.readFileSync(presetsFile,'utf8').replace(/^\uFEFF/,''));
(async()=>{
 fs.mkdirSync(output,{recursive:true});const {chromium}=require(modulePath),browser=await chromium.launch({channel:'chrome',headless:true});
 const page=await browser.newPage({viewport:{width:1200,height:1050}}),checks=[],errors=[];page.on('pageerror',e=>errors.push(e.stack));
 try{
  await page.setContent('<main id="workspace-content" style="width:360px;overflow:auto;height:1000px"><section id="group-materials"></section><section id="group-shell-properties"></section><section id="group-beam-sections"></section></main>');
  const html=fs.readFileSync(path.join(web,'index.html'),'utf8');for(const[,file]of html.matchAll(/<link[^>]+rel="stylesheet"[^>]+href="([^"?]+)(?:\?[^\"]*)?"/g))await page.addStyleTag({content:fs.readFileSync(path.join(web,file),'utf8')});
  for(const file of ['reference_import.js','workspace.js','materials_editor.js','material_allowables.js'])await page.addScriptTag({path:path.join(web,file)});
  await page.evaluate(presets=>{
   window.presets=presets;window.edits=[];window.savedRows=[{material_id:1,mode:'stress',stress:300e6}];
   const params={'material.name':'Al2024 existing','material.E':71,'material.nu':.33,'material.rho':2780,'materials.library':[{id:2,name:'Existing steel',E:210e9,nu:.3,rho:7850},{id:3,name:'Existing core',E:100e6,nu:.3,rho:80},{id:9,name:'Existing custom alloy',E:69e9,nu:.29,rho:2730}],'materials.shells':[{component:'upper_skin',kind:'monolithic',material:1,face_material:1,core_material:3,face_thickness:.0005,core_thickness:.01},{component:'lower_skin',kind:'monolithic',material:9,face_material:1,core_material:3,face_thickness:.0005,core_thickness:.01}],'materials.bars':[{component:'stringer',material:2}]};
   for(const[key,value]of Object.entries(params)){const row=document.createElement('label');row.className='row';const input=document.createElement('input');input.id='p-'+key;input.value=Array.isArray(value)?JSON.stringify(value):String(value);row.append(input);document.getElementById('group-materials').append(row);}
   window.initialLibrary=JSON.parse(JSON.stringify(params['materials.library']));
   window.install=()=>{
    window.materialEditor=WingMaterialsEditor.install({document,presets,onEdit:key=>edits.push(key)});
    window.allowableEditor=WingMaterialAllowables.editor({document,host:materialEditor.allowablesHost,materialLibrary:materialEditor,readMaterials:()=>[{id:1,type:'MAT1',name:document.getElementById('p-material.name').value},...materialEditor.readDrafts()['materials.library'].map(row=>({...row,type:'MAT1'}))],readRows:()=>savedRows,onChange:rows=>savedRows=rows});
   };install();
  },presets);
  const material=page.locator('#material-library-select'),preset=page.locator('#material-preset-select');
  await preset.selectOption({label:'Al7075-T6 DTD5014'});await page.locator('#material-preset-add').click();assert.equal(await material.inputValue(),'4');
  await preset.selectOption({label:'Al2024-T3 DTD5070B'});await page.locator('#material-preset-add').click();assert.equal(await material.inputValue(),'5');
  const added=await page.evaluate(()=>materialEditor.readDrafts()['materials.library']);
  assert.deepEqual(added.filter(row=>[2,3,9].includes(row.id)),await page.evaluate(()=>initialLibrary));assert.deepEqual(added.map(row=>row.id),[2,3,4,5,9]);
  for(const[id,name,E,rho,uts,shear,C2,m,fn]of[[4,'Al7075-T6 DTD5014',76e9,2810,572e6,331e6,487e6,22.2,444e6],[5,'Al2024-T3 DTD5070B',73.1e9,2780,483e6,283e6,342e6,16.6,301e6]]){
   const row=added.find(row=>row.id===id);assert.equal(row.name,name);assert.equal(row.E,E);assert.equal(row.rho,rho);assert.equal(row.nu,.33);assert.deepEqual([row.reference_data.ultimate_tensile_Pa,row.reference_data.shear_Pa,row.reference_data.compression_proof_Pa,row.reference_data.m,row.reference_data.fn_Pa],[uts,shear,C2,m,fn]);assert.match(row.reference_data.poisson_note,/assumed/);
  }
  const before=await page.evaluate(()=>materialEditor.readDrafts());assert.equal(before['materials.shells'].find(row=>row.component==='lower_skin').material,9);assert.equal(before['materials.bars'].find(row=>row.component==='stringer').material,2);
  checks.push('Adding both report alloys allocates unused IDs, preserves existing material definitions and leaves existing component assignments unchanged.');
  await page.getByLabel('Upper skin material',{exact:true}).selectOption('4');await page.getByLabel('Lower skin material',{exact:true}).selectOption('5');await page.getByLabel('Stringers material',{exact:true}).selectOption('4');
  await material.selectOption('4');await page.getByLabel('Material 4 name',{exact:true}).fill('Al7075-T6 DTD5014 - editable copy');await page.locator('.material-library-row:visible').getByLabel('Poisson ratio',{exact:true}).fill('.32');
  await page.locator('#allowable-mode').selectOption('stress');await page.locator('#allowable-stress').fill('400');
  assert.equal(await page.locator('.material-library-row:visible').getByLabel('E (GPa)',{exact:true}).inputValue(),'76');await page.locator('.material-reference-data:visible > summary').click();assert.match(await page.locator('.material-reference-data:visible').innerText(),/572 MPa/);assert.match(await page.locator('.material-reference-data:visible').innerText(),/distinct from.*von Mises/i);
  const persisted=await page.evaluate(async()=>{
   materialEditor.assertValidDraft();const parameters={...materialEditor.readDrafts(),'materials.allowables':savedRows};
   const view={controls:{},layers:{},camera:{target:[0,0,0],alpha:0,beta:1,radius:2},workspace:{activeTab:'material',width:360,collapsed:false},activeCase:1};
   const study=await WingWorkspace.snapshot(parameters,null,view);window.savedStudy=JSON.stringify(study);const reopened=WingWorkspace.parse(savedStudy).data;
   materialEditor.destroy();allowableEditor.destroy();for(const key of ['materials.library','materials.shells','materials.bars'])document.getElementById('p-'+key).value=JSON.stringify(reopened.parameters[key]);savedRows=reopened.parameters['materials.allowables'];install();return reopened.parameters;
  });
  const upper=persisted['materials.library'].find(row=>row.id===4),lower=persisted['materials.library'].find(row=>row.id===5);assert.deepEqual(upper.reference_data,added.find(row=>row.id===4).reference_data);assert.equal(upper.E,76e9);assert.equal(upper.rho,2810);assert.equal(upper.nu,.32);assert.equal(lower.E,73.1e9);assert.equal(lower.rho,2780);
  assert.equal(persisted['materials.shells'].find(row=>row.component==='upper_skin').material,4);assert.equal(persisted['materials.shells'].find(row=>row.component==='lower_skin').material,5);assert.equal(persisted['materials.bars'].find(row=>row.component==='stringer').material,4);
  await material.selectOption('4');assert.equal(await page.locator('#allowable-stress').inputValue(),'400');assert.equal(await page.getByLabel('Material 4 name',{exact:true}).inputValue(),'Al7075-T6 DTD5014 - editable copy');
  await page.locator('.material-reference-data:visible > summary').click();
  assert.equal(await page.getByLabel('Upper skin material',{exact:true}).inputValue(),'4');assert.equal(await page.getByLabel('Lower skin material',{exact:true}).inputValue(),'5');assert.equal(await page.getByLabel('Stringers material',{exact:true}).inputValue(),'4');
  checks.push('User edits, component assignments, source strengths and explicit MPa allowable survive real Study snapshot/parse and editor reconstruction without altering the source preset.');
  assert.deepEqual(await page.evaluate(()=>window.presets),presets);
  const widths=[];for(const width of [280,360,1000]){await page.locator('#workspace-content').evaluate((node,w)=>node.style.width=w+'px',width);const overflow=await page.evaluate(()=>{const box=document.getElementById('workspace-content').getBoundingClientRect();return[...document.querySelectorAll('.materials-library input,.materials-library select,.material-reference-data')].filter(node=>node.getClientRects().length).filter(node=>{const rect=node.getBoundingClientRect();return rect.left<box.left-1||rect.right>box.right+1}).map(node=>node.id||node.getAttribute('aria-label')||node.className);});assert.deepEqual(overflow,[],width+'px pane');widths.push(width);}
  await page.locator('#workspace-content').evaluate(node=>node.style.width='280px');await page.locator('.materials-library').screenshot({path:path.join(output,'report_alloy_library_280.png')});
  assert.equal(await page.locator('#material-preset-select').count(),1);assert.deepEqual(errors,[]);checks.push('Preset selector and source-strength details fit 280, 360 and 1000 pixel panes; no duplicate selectors or browser errors.');
  fs.writeFileSync(path.join(output,'report_alloy_study.wingfem.json'),await page.evaluate(()=>savedStudy));fs.writeFileSync(path.join(output,'report_alloy_browser_check.json'),JSON.stringify({passed:true,checks,widths,errors},null,2));console.log(JSON.stringify({passed:true,checks,widths}));
 }catch(error){await page.screenshot({path:path.join(output,'report_alloy_error.png')});fs.writeFileSync(path.join(output,'report_alloy_error.json'),JSON.stringify({error:error.stack,checks,errors},null,2));throw error;}finally{await browser.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});
